function waitFor(el,event,limit=20000){return new Promise((resolve,reject)=>{const timer=setTimeout(()=>finish(Error('Không đọc được tư liệu. Hãy thử định dạng khác.')),limit);const ok=()=>finish(),bad=()=>finish(Error('Trình duyệt không giải mã được tư liệu.'));function finish(error){clearTimeout(timer);el.removeEventListener(event,ok);el.removeEventListener('error',bad);error?reject(error):resolve();}el.addEventListener(event,ok,{once:true});el.addEventListener('error',bad,{once:true});});}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function store(){return new Promise((resolve,reject)=>{const r=indexedDB.open('fbtq-creative-studio',2);r.onupgradeneeded=()=>{for(const name of ['assets','projects','edits'])if(!r.result.objectStoreNames.contains(name))r.result.createObjectStore(name,{keyPath:'key'});};r.onsuccess=()=>{r.result.onversionchange=()=>r.result.close();resolve(r.result);};r.onerror=()=>reject(r.error);r.onblocked=()=>reject(Error('Đóng các tab FBTQ khác rồi tải lại để nâng cấp kho Studio.'));});}
async function record(name,method,value){const db=await store();try{return await new Promise((resolve,reject)=>{const tx=db.transaction(name,method==='getAll'?'readonly':'readwrite'),r=tx.objectStore(name)[method](value);let result;r.onsuccess=()=>result=r.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Không thể lưu dự án.'));});}finally{db.close();}}
