 document.addEventListener('visibilitychange',()=>{if(document.hidden){if(recording){abort=true;status('Đã huỷ xuất vì tab bị ẩn. Giữ tab hiển thị khi xuất.');}stop();}});window.addEventListener('beforeunload',e=>{if(dirty||recording){e.preventDefault();e.returnValue='';}});document.addEventListener('fbtq:creative-open',()=>action(load));new MutationObserver(()=>{if(!root.classList.contains('active')){if(recording)abort=true;stop();}}).observe(root,{attributes:true,attributeFilter:['class']});new MutationObserver(()=>{if(owner&&state.user?.uid!==owner)reset();}).observe($('#app'),{attributes:true,attributeFilter:['class']});timelineView=createTimelineView({root,scroll,timeline:q('#csTimeline'),getZoom:()=>zoom,getTime:()=>time,getDuration:total,onSeek:value=>{if(recording)return;stop();time=value;preview().catch(e=>status(e.message,true));},onStop:stop,getTool:()=>tool,disabled:()=>busy||recording||mode!=='video'});editorChrome=initEditorChrome(root,{zoomBy:delta=>zoomTo(zoom+delta),onVisualAction:kind=>action(async()=>{const c=current();if(!c||['audio','effect'].includes(c.type))return;stop();remember();if(kind==='rotate')c.rotation=((c.rotation||0)+90)%360;else{c.fit=kind;c.x=0;c.y=0;c.w=1;c.h=1;}render();await preview();})});imageEditor=initImageEditor(root,{getState:()=>({mode,current:current(),layers:imageLayers,frame:dimensions()}),change:imageChange,add:imageAdd,background:color=>action(async()=>{if(mode!=='image')return;imageBackground(color);render();await preview();}),replaceImage:file=>action(async(u,g)=>{const c=current();if(mode!=='image'||c?.type!=='image'||c.locked)return;const id=c.id,key=await ingest(file,file.name,u,g);guard(u,g);if(current()?.id!==id)return;remember();Object.assign(c,{mediaId:key,name:file.name});render();await preview();})});workspaceResize=initWorkspaceResize(root,{disabled:()=>busy||recording});reset();
 return {load:()=>action(load),getSnapshot:()=>structuredClone({owner,mode,tracks,clips,imageLayers,time,frame:dimensions(),zoom,scrollLeft:scroll.scrollLeft}),reset};
